$path='admin-panel/app/islamic-lifestyle/page.tsx'
$text=Get-Content -Raw $path
$old='[deleteTarget,setDeleteTarget]=useState<any|null>(null),[deleting,setDeleting]=useState(false);'
$new='[deleteTarget,setDeleteTarget]=useState<any|null>(null),[deleting,setDeleting]=useState(false),[previewTarget,setPreviewTarget]=useState<any|null>(null),[chapterFilter,setChapterFilter]=useState("all");'
if(-not $text.Contains($old)){throw 'Admin state insertion point not found'}
$text=$text.Replace($old,$new)
$text=$text.Replace(' const categories=items.filter(x=>x.kind==="category");',' const categories=items.filter(x=>x.kind==="category");' + "`r`n" + ' const chapters=items.filter(x=>x.kind==="chapter");' + "`r`n" + ' const visibleChapters=chapterFilter==="all"?chapters:chapters.filter(x=>x.parentCategorySlug===chapterFilter);' + "`r`n" + ' const categoryName=(slug:string)=>categories.find(x=>x.slug===slug)?.title||"Unassigned category";')
$panelHead='<section className="panel list"><div className="panelHead"><div><small>APP STRUCTURE</small><h2>Categories & chapters</h2></div></div>'
$library=@'
<section className="panel list"><div className="panelHead"><div><small>APP STRUCTURE</small><h2>Categories & chapters</h2></div></div><div className="chapterLibrary"><div className="libraryHead"><div><small>CHAPTER CONTENT LIBRARY</small><h3>Saved chapter content</h3><p>Preview or edit every chapter published from this admin panel.</p></div><b>{chapters.length}</b></div><select className="chapterFilter" value={chapterFilter} onChange={event=>setChapterFilter(event.target.value)}><option value="all">All categories ({chapters.length})</option>{categories.map(category=><option key={category.slug} value={category.slug}>{category.title} ({chapters.filter(chapter=>chapter.parentCategorySlug===category.slug).length})</option>)}</select><div className="chapterContentList">{visibleChapters.length?visibleChapters.map(chapter=><article className="chapterContentCard" key={chapter.id}><div className="chapterContentNumber">{String(chapter.order||1).padStart(2,"0")}</div><div className="chapterContentCopy"><small>{categoryName(chapter.parentCategorySlug)}</small><b>{chapter.title}</b><span>{chapter.subtitle||"No subtitle"} • {chapter.published?"Published":"Draft"}</span></div><div className="chapterContentActions"><button type="button" className="viewButton" onClick={()=>setPreviewTarget(chapter)}>View</button><button type="button" onClick={()=>edit(chapter)}>Edit</button><button type="button" className="delete" onClick={()=>setDeleteTarget(chapter)}>Delete</button></div></article>):<div className="emptyChapters"><b>No chapter content yet</b><span>Select “Chapter inside category” in the form and create the first chapter.</span></div>}</div></div>
'@
if(-not $text.Contains($panelHead)){throw 'Right panel heading not found'}
$text=$text.Replace($panelHead,$library)
$deleteNeedle='{deleteTarget&&<div className="deleteModal"'
if(-not $text.Contains($deleteNeedle)){throw 'Modal area not found'}
$previewModal='<div className="previewModal" role="dialog" aria-modal="true"><div className="previewDialog"><div className="previewTop"><div><small>{categoryName(previewTarget.parentCategorySlug)}</small><h2>{previewTarget.title}</h2><p>{previewTarget.subtitle}</p></div><button type="button" onClick={()=>setPreviewTarget(null)}>x</button></div><iframe title={previewTarget.title} sandbox="" srcDoc={`<!doctype html><html><head><meta charset="utf-8"><style>body{padding:22px;font:16px/1.75 Arial;color:#29483a}h1,h2,h3,h4{color:#075b3b}blockquote{padding:12px 16px;border-left:4px solid #c6a64d;background:#fff9e7}img{max-width:100%;height:auto;border-radius:12px}a{color:#087a4d}</style></head><body>${previewTarget.introduction?.join("")||"<p>No chapter content.</p>"}</body></html>`}/><div className="previewActions"><button type="button" className="secondary" onClick={()=>setPreviewTarget(null)}>Close</button><button type="button" onClick={()=>{setPreviewTarget(null);edit(previewTarget)}}>Edit chapter</button></div></div></div>'
$text=$text.Replace($deleteNeedle,'{previewTarget&&'+$previewModal+'}{deleteTarget&&<div className="deleteModal"')
$css='.chapterLibrary{margin-bottom:24px;padding:16px;border:1px solid #dce8df;border-radius:17px;background:#f7fbf8}.libraryHead{display:flex;align-items:center}.libraryHead>div{flex:1}.libraryHead small{font-size:9px;font-weight:900;letter-spacing:1px;color:#a17e24}.libraryHead h3{margin:4px 0;border:0;padding:0;font-size:18px}.libraryHead p{margin:4px 0 0;color:#718078;font-size:11px}.libraryHead>b{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;background:#e2f3e7;color:#087a4d;font-size:17px}.chapterFilter{margin:13px 0;background:#fff}.chapterContentList{display:grid;gap:9px}.chapterContentCard{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid #dce8df;border-radius:13px;background:#fff}.chapterContentNumber{width:35px;height:35px;border-radius:11px;display:grid;place-items:center;background:#087a4d;color:#fff;font-size:10px;font-weight:900}.chapterContentCopy{min-width:0;flex:1}.chapterContentCopy small,.chapterContentCopy b,.chapterContentCopy span{display:block}.chapterContentCopy small{font-size:8px;color:#a17e24;font-weight:900;text-transform:uppercase}.chapterContentCopy b{margin-top:3px;font-size:12px}.chapterContentCopy span{margin-top:3px;color:#718078;font-size:9px}.chapterContentActions{display:flex;gap:5px}.chapterContentActions button{padding:7px 8px;font-size:10px;margin:0}.viewButton{background:#e7f4ea!important;color:#087a4d!important}.emptyChapters{padding:25px;text-align:center;border:1px dashed #bfd2c5;border-radius:13px;background:#fff}.emptyChapters b,.emptyChapters span{display:block}.emptyChapters span{margin-top:5px;color:#718078;font-size:10px}.previewModal{position:fixed;inset:0;z-index:1001;display:grid;place-items:center;padding:20px;background:rgba(10,35,25,.58);backdrop-filter:blur(3px)}.previewDialog{width:min(760px,100%);height:min(760px,90vh);padding:18px;border-radius:22px;background:#fff;display:flex;flex-direction:column;box-shadow:0 25px 80px rgba(0,0,0,.28)}.previewTop{display:flex;align-items:flex-start;padding:3px 4px 13px}.previewTop>div{flex:1}.previewTop small{font-size:9px;font-weight:900;color:#a17e24}.previewTop h2{margin:4px 0}.previewTop p{margin:0;color:#718078}.previewTop>button{width:34px;height:34px;padding:0;border-radius:50%;background:#e7f4ea;color:#173d2e}.previewDialog iframe{width:100%;flex:1;border:1px solid #dce8df;border-radius:14px;background:#fff}.previewActions{display:flex;justify-content:flex-end;gap:9px;padding-top:13px}@media(max-width:700px){.chapterContentCard{align-items:flex-start;flex-wrap:wrap}.chapterContentActions{width:100%;justify-content:flex-end}}'
$text=$text.Replace('*{box-sizing:border-box}','*{box-sizing:border-box}'+$css)
Set-Content -Path $path -Value $text -Encoding utf8
